package ec.dmt.admin.school;
import jakarta.persistence.*;
@Entity @Table(name="course") public class Course { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false,unique=true) private String name; @Column(nullable=false) private boolean active=true; @Column(name="course_order",nullable=false) private int courseOrder; @Column(nullable=false) private String level; protected Course(){} public Course(String name, boolean active){this(name,active,0,"EGB");} public Course(String name,boolean active,int courseOrder,String level){this.name=name;this.active=active;this.courseOrder=courseOrder;this.level=level;} public Long getId(){return id;} public String getName(){return name;} public boolean isActive(){return active;} public int getCourseOrder(){return courseOrder;} public String getLevel(){return level;} public void update(String name,boolean active){this.name=name;this.active=active;} }
